$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$python = Join-Path $root ".venv\Scripts\python.exe"

$storyPath = Join-Path $pkg "ahos\story_engine.py"
$testPath = Join-Path $pkg "tests\test_story_engine.py"
$backlogPath = Join-Path $pkg "STUDIO_BACKLOG.json"
$reportPath = Join-Path $pkg "reports\STUDIO-003-story-engine-proof.json"

$privateRoot = Join-Path $root "runtime\private\animation-studio"
$characterDb = Join-Path $privateRoot "character-memory.db"
$episodeDb = Join-Path $privateRoot "episode-planning.db"
$privatePacket = Join-Path $privateRoot "episodes\S01E001\story-packet.local.json"

$patcher = Join-Path $env:TEMP "studio-003-backlog.py"
$proof = Join-Path $env:TEMP "studio-003-proof.py"

Write-Host "=== STUDIO-003 STORY + EPISODE PLANNING ENGINE ==="
Write-Host "PRIVATE STORY DATA: LOCAL ONLY"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host ""

if (-not (Test-Path $python)) { throw "Python venv not found." }
if (-not (Test-Path $pkg)) { throw "AHOS package not found." }
if (-not (Test-Path $characterDb)) {
    throw "STUDIO-002 Character Bible DB not found: $characterDb"
}

New-Item -ItemType Directory -Force -Path (Split-Path $reportPath -Parent) | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path $privatePacket -Parent) | Out-Null

[IO.File]::WriteAllBytes(
    $storyPath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $testPath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $patcher,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $proof,
    [Convert]::FromBase64String("")
)

$old = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg

    Write-Host "Running Story Engine focused tests..."
    & $python -m pytest tests\test_story_engine.py -q
    if ($LASTEXITCODE -ne 0) {
        throw "STUDIO-003 focused tests failed."
    }

    Write-Host "Running full AHOS + Studio regression suite..."
    & $python -m pytest -q
    if ($LASTEXITCODE -ne 0) {
        throw "Full regression suite failed."
    }

    Write-Host "Running private zero-cost episode planning proof..."
    & $python $proof $characterDb $episodeDb $privatePacket $reportPath
    if ($LASTEXITCODE -ne 0) {
        throw "STUDIO-003 local proof failed."
    }

    & $python $patcher $backlogPath
    if ($LASTEXITCODE -ne 0) {
        throw "STUDIO-003 backlog update failed."
    }
}
finally {
    Pop-Location
    $env:PYTHONPATH = $old
    Remove-Item $patcher -Force -ErrorAction SilentlyContinue
    Remove-Item $proof -Force -ErrorAction SilentlyContinue
}

# Private story/cast databases and packets must remain outside nested Git repo.
$repoResolved = [IO.Path]::GetFullPath($ws)
$privateResolved = [IO.Path]::GetFullPath($privateRoot)
if ($privateResolved.StartsWith($repoResolved, [StringComparison]::OrdinalIgnoreCase)) {
    throw "Privacy guard failed: private studio data is inside Git repository."
}

git -C $ws add `
    ahos_core/ahos/story_engine.py `
    ahos_core/tests/test_story_engine.py `
    ahos_core/STUDIO_BACKLOG.json `
    ahos_core/reports/STUDIO-003-story-engine-proof.json

$staged = git -C $ws diff --cached --name-only
if ($staged -match "episode-planning\.db|story-packet\.local|character-memory\.db") {
    throw "Privacy guard failed: private episode data was staged."
}

if ($staged) {
    git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" `
        commit -m "feat(studio): add story episode planning engine"
    if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

    git -C $ws push origin HEAD
    if ($LASTEXITCODE -ne 0) { throw "git push failed." }
}

Write-Host ""
Write-Host "=== STUDIO-003 COMPLETE ==="
Write-Host "Character Bible context injection: PASS"
Write-Host "Season-aware episode IDs: PASS"
Write-Host "Story beat planning: PASS"
Write-Host "Scene + dialogue packet model: PASS"
Write-Host "Exact episode duration validation: PASS"
Write-Host "Unknown/invented cast rejection: PASS"
Write-Host "Persistent versioned episode planning DB: PASS"
Write-Host "Explicit owner approval/rejection: PASS"
Write-Host "AI self-approval: BLOCKED"
Write-Host "Structured AI story-planner adapter: READY (not called)"
Write-Host "Private story data kept OUTSIDE Git: PASS"
Write-Host "Full regression suite: PASS"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host ""
Write-Host "PRIVATE EPISODE DB: $episodeDb"
Write-Host "NEXT: STUDIO-004 Scene, Shot, Prompt and Asset Graph."
